import 'dart:typed_data';
import 'package:excel/excel.dart' as ex;
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:intl/intl.dart';
import 'package:path/path.dart' as p;
import 'package:sqflite/sqflite.dart';
void main() async { WidgetsFlutterBinding.ensureInitialized(); await AppDb.i.db; runApp(const App()); }
class App extends StatelessWidget { const App({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Recuentos',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff1554a3)),useMaterial3:true,inputDecorationTheme:const InputDecorationTheme(border:OutlineInputBorder())),home:const Home()); }
class Session { final int id; final String zone; final bool done; final String? file; final DateTime updated; const Session(this.id,this.zone,this.done,this.file,this.updated); factory Session.fromMap(Map<String,Object?>m)=>Session(m['id'] as int,m['zone'] as String,(m['done'] as int)==1,m['file'] as String?,DateTime.parse(m['updated'] as String)); }
class Rec { final int? id; final int sid; final String inv,label; final double kg; final DateTime at; const Rec(this.id,this.sid,this.inv,this.label,this.kg,this.at); factory Rec.fromMap(Map<String,Object?>m)=>Rec(m['id'] as int,m['sid'] as int,m['inv'] as String,m['label'] as String,(m['kg'] as num).toDouble(),DateTime.parse(m['at'] as String)); }
class AppDb { AppDb._(); static final i=AppDb._(); Database? _d; Future<Database> get db async { if(_d!=null)return _d!; _d=await openDatabase(p.join(await getDatabasesPath(),'recuentos.db'),version:1,onCreate:(d,v)async{await d.execute('CREATE TABLE sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,zone TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,file TEXT,updated TEXT NOT NULL)');await d.execute('CREATE TABLE records(id INTEGER PRIMARY KEY AUTOINCREMENT,sid INTEGER NOT NULL,inv TEXT NOT NULL,label TEXT NOT NULL,kg REAL NOT NULL,at TEXT NOT NULL)');});return _d!;} Future<int> create(String z)async=>(await db).insert('sessions',{'zone':z,'done':0,'updated':DateTime.now().toIso8601String()}); Future<List<Session>> sessions(bool done)async{final a=await(await db).query('sessions',where:'done=?',whereArgs:[done?1:0],orderBy:'updated DESC');return a.map(Session.fromMap).toList();} Future<List<Rec>> recs(int sid)async{final a=await(await db).query('records',where:'sid=?',whereArgs:[sid],orderBy:'id ASC');return a.map(Rec.fromMap).toList();} Future<void> add(Rec r)async{final d=await db;await d.transaction((t)async{await t.insert('records',{'sid':r.sid,'inv':r.inv,'label':r.label,'kg':r.kg,'at':r.at.toIso8601String()});await t.update('sessions',{'updated':DateTime.now().toIso8601String()},where:'id=?',whereArgs:[r.sid]);});} Future<void> del(int id)async{await(await db).delete('records',where:'id=?',whereArgs:[id]);} Future<void> finish(int id,String f)async{await(await db).update('sessions',{'done':1,'file':f,'updated':DateTime.now().toIso8601String()},where:'id=?',whereArgs:[id]);}}
class Exporter { static const ch=MethodChannel('recuento/downloads'); static Future<String> save(Session s,List<Rec> rs)async{final b=ex.Excel.createExcel();final sh=b['Recuento'];final old=b.getDefaultSheet();if(old!=null&&old!='Recuento')b.delete(old);sh.appendRow([ex.TextCellValue('ZONA'),ex.TextCellValue('NUMERO INVENTARIO'),ex.TextCellValue('ETIQUETA ESCANEADA'),ex.TextCellValue('KG')]);for(final r in rs){sh.appendRow([ex.TextCellValue(s.zone),ex.TextCellValue(r.inv),ex.TextCellValue(r.label),ex.DoubleCellValue(r.kg)]);}final bytes=b.encode();if(bytes==null)throw Exception('No se pudo crear Excel');final z=s.zone.trim().replaceAll(RegExp(r'[\\/:*?"<>|\s]+'),'_');final n='${z.isEmpty?'ZONA':z}_${DateFormat('dd-MM-yyyy_HH-mm-ss').format(DateTime.now())}.xlsx';return await ch.invokeMethod<String>('save',{'name':n,'bytes':Uint8List.fromList(bytes)})??n;}}
class Home extends StatelessWidget { const Home({super.key}); Future<void> start(BuildContext c)async{final x=TextEditingController();final z=await showDialog<String>(context:c,builder:(d)=>AlertDialog(title:const Text('NUEVO RECUENTO'),content:TextField(controller:x,autofocus:true,decoration:const InputDecoration(labelText:'Zona'),onSubmitted:(v){if(v.trim().isNotEmpty)Navigator.pop(d,v.trim());}),actions:[FilledButton(onPressed:(){if(x.text.trim().isNotEmpty)Navigator.pop(d,x.text.trim());},child:const Text('EMPEZAR'))]));if(z==null||!c.mounted)return;final id=await AppDb.i.create(z);if(c.mounted)Navigator.push(c,MaterialPageRoute(builder:(_)=>Flow(Session(id,z,false,null,DateTime.now()))));} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('RECUENTOS')),body:Center(child:SizedBox(width:520,child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.stretch,children:[FilledButton(onPressed:()=>start(c),child:const Padding(padding:EdgeInsets.all(18),child:Text('NUEVO RECUENTO'))),const SizedBox(height:14),OutlinedButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const Sessions(false))),child:const Text('CONTINUAR RECUENTO')),const SizedBox(height:14),OutlinedButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const Sessions(true))),child:const Text('RECUENTOS FINALIZADOS'))])))));}
class Sessions extends StatefulWidget {final bool done;const Sessions(this.done,{super.key});@override State<Sessions>createState()=>_SessionsState();} class _SessionsState extends State<Sessions>{late Future<List<Session>> f;@override void initState(){super.initState();f=AppDb.i.sessions(widget.done);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.done?'FINALIZADOS':'CONTINUAR')),body:FutureBuilder<List<Session>>(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data!;if(a.isEmpty)return const Center(child:Text('No hay recuentos'));return ListView.builder(itemCount:a.length,itemBuilder:(c,i){final x=a[i];return ListTile(title:Text(x.zone),subtitle:Text(x.file??DateFormat('dd/MM/yyyy HH:mm').format(x.updated)),trailing:widget.done?const Icon(Icons.check_circle):const Icon(Icons.chevron_right),onTap:widget.done?null:()async{await Navigator.push(c,MaterialPageRoute(builder:(_)=>Flow(x)));if(mounted)setState(()=>f=AppDb.i.sessions(false));});});}));}
enum Phase{inventory,label,kg}
class Flow extends StatefulWidget {final Session s;const Flow(this.s,{super.key});@override State<Flow>createState()=>_FlowState();} class _FlowState extends State<Flow>{Phase phase=Phase.inventory;final inv=TextEditingController(),lab=TextEditingController(),kg=TextEditingController();final focus=FocusNode();List<Rec> rows=[];@override void initState(){super.initState();load();WidgetsBinding.instance.addPostFrameCallback((_){focus.requestFocus();});}@override void dispose(){inv.dispose();lab.dispose();kg.dispose();focus.dispose();super.dispose();}Future<void> load()async{final a=await AppDb.i.recs(widget.s.id);if(mounted)setState(()=>rows=a);}TextEditingController get ctl=>switch(phase){Phase.inventory=>inv,Phase.label=>lab,Phase.kg=>kg};String get title=>switch(phase){Phase.inventory=>'NÚMERO DE INVENTARIO',Phase.label=>'ESCANEE LA ETIQUETA',Phase.kg=>'INTRODUZCA KILOS'};TextInputType get keyboard=>phase==Phase.label?TextInputType.none:const TextInputType.numberWithOptions(decimal:true);
void refocus(){WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)focus.requestFocus();});}Future<void> next(String raw)async{final v=raw.trim();if(v.isEmpty){refocus();return;}if(phase==Phase.inventory){setState(()=>phase=Phase.label);refocus();return;}if(phase==Phase.label){setState(()=>phase=Phase.kg);refocus();return;}final n=double.tryParse(v.replaceAll(',','.'));if(n==null||n<0){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Introduzca kilos válidos')));refocus();return;}await AppDb.i.add(Rec(null,widget.s.id,inv.text.trim(),lab.text.trim(),n,DateTime.now()));inv.clear();lab.clear();kg.clear();await load();if(mounted){setState(()=>phase=Phase.inventory);refocus();}}
Future<void> erase(Rec r)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('¿Eliminar este registro?'),content:Text('Inventario: ${r.inv}\n${r.kg.toStringAsFixed(2)} kg'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('ELIMINAR'))]))??false;if(ok&&r.id!=null){await AppDb.i.del(r.id!);await load();refocus();}}
Future<void> end()async{if(rows.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No hay registros')));return;}final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('FINALIZAR RECUENTO'),content:Text('Se exportarán ${rows.length} registros a Excel.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('FINALIZAR'))]))??false;if(!ok){refocus();return;}final f=await Exporter.save(widget.s,rows);await AppDb.i.finish(widget.s.id,f);if(!mounted)return;await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('GUARDADO'),content:Text('Excel guardado en Descargas:\n$f'),actions:[FilledButton(onPressed:()=>Navigator.pop(d),child:const Text('ACEPTAR'))]));if(mounted)Navigator.pop(context);}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.s.zone),actions:[IconButton(onPressed:end,icon:const Icon(Icons.save_alt))]),body:SafeArea(child:Column(children:[Expanded(flex:5,child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:600),child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(title,textAlign:TextAlign.center,style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:24),TextField(key:ValueKey(phase),controller:ctl,focusNode:focus,autofocus:true,keyboardType:keyboard,textInputAction:TextInputAction.done,textAlign:TextAlign.center,style:const TextStyle(fontSize:30,fontWeight:FontWeight.bold),decoration:InputDecoration(suffixText:phase==Phase.kg?'kg':null,border:const OutlineInputBorder()),onSubmitted:next),const SizedBox(height:16),FilledButton(onPressed:()=>next(ctl.text),child:const Text('ACEPTAR')),const SizedBox(height:8),TextButton.icon(onPressed:end,icon:const Icon(Icons.check_circle_outline),label:const Text('FINALIZAR RECUENTO'))]))))),const Divider(height:1),Expanded(flex:5,child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,10,16,6),child:Row(children:[Text('REGISTROS GUARDADOS (${rows.length})',style:const TextStyle(fontWeight:FontWeight.bold)),const Spacer()])),Expanded(child:rows.isEmpty?const Center(child:Text('Sin registros guardados')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(c,i){final r=rows[rows.length-1-i];return ListTile(dense:true,leading:CircleAvatar(child:Text('${rows.length-i}')),title:Text('Inv. ${r.inv}   •   ${r.kg.toStringAsFixed(2)} kg'),subtitle:Text(r.label,maxLines:2,overflow:TextOverflow.ellipsis),trailing:IconButton(icon:const Icon(Icons.delete_outline,color:Colors.red),tooltip:'Eliminar registro',onPressed:()=>erase(r)));}))]))])));}
